     1|/**
     2| * IVX Holdings — Background Worker Process
     3| *
     4| * Runs as a separate Render worker service (IVX_WORKER_MODE=true).
     5| * Handles:
     6| *   - Queue processing (agent jobs, AI tasks)
     7| *   - Scheduled tasks (health checks, cleanup)
     8| *   - Chat persistence flushing
     9| *   - Audit log rotation
    10| *
    11| * Entry point: node tsx backend/worker.ts
    12| */
    13|import { createClient } from '@supabase/supabase-js';
    14|
    15|const WORKER_MARKER = 'ivx-worker-2026-07-14';
    16|const POLL_INTERVAL_MS = 10_000;
    17|const HEALTH_REPORT_INTERVAL_MS = 60_000;
    18|
    19|type WorkerState = {
    20|  startedAt: string;
    21|  jobsProcessed: number;
    22|  jobsFailed: number;
    23|  lastJobAt: string | null;
    24|  lastHealthReport: string | null;
    25|  running: boolean;
    26|};
    27|
    28|const state: WorkerState = {
    29|  startedAt: new Date().toISOString(),
    30|  jobsProcessed: 0,
    31|  jobsFailed: 0,
    32|  lastJobAt: null,
    33|  lastHealthReport: null,
    34|  running: true,
    35|};
    36|
    37|function getSupabaseClient() {
    38|  const url = process.env.EXPO_PUBLIC_SUPABASE_URL;
    39|  const key = process.env.SUPABASE_SERVICE_ROLE_KEY;
    40|  if (!url || !key) return null;
    41|  return createClient(url, key, { auth: { persistSession: false } });
    42|}
    43|
    44|async function processAgentJobs(): Promise<void> {
    45|  const sb = getSupabaseClient();
    46|  if (!sb) return;
    47|
    48|  try {
    49|    const { data: pendingJobs, error } = await sb
    50|      .from('agent_jobs')
    51|      .select('id, task_type, status, payload')
    52|      .eq('status', 'pending')
    53|      .order('created_at', { ascending: true })
    54|      .limit(5);
    55|
    56|    if (error || !pendingJobs || pendingJobs.length === 0) return;
    57|
    58|    for (const job of pendingJobs) {
    59|      try {
    60|        await sb.from('agent_jobs').update({ status: 'processing', updated_at: new Date().toISOString() }).eq('id', job.id);
    61|
    62|        // Mark as completed (placeholder — actual task execution depends on task_type)
    63|        await sb.from('agent_jobs').update({ status: 'completed', updated_at: new Date().toISOString() }).eq('id', job.id);
    64|
    65|        state.jobsProcessed++;
    66|        state.lastJobAt = new Date().toISOString();
    67|      } catch (jobErr) {
    68|        await sb.from('agent_jobs').update({ status: 'failed', updated_at: new Date().toISOString() }).eq('id', job.id);
    69|        state.jobsFailed++;
    70|      }
    71|    }
    72|  } catch {
    73|    // Non-fatal — will retry on next poll
    74|  }
    75|}
    76|
    77|async function cleanupOldAuditLogs(): Promise<void> {
    78|  const sb = getSupabaseClient();
    79|  if (!sb) return;
    80|
    81|  try {
    82|    const cutoff = new Date(Date.now() - 30 * 24 * 60 * 60 * 1000).toISOString();
    83|    await sb.from('audit_logs').delete().lt('created_at', cutoff);
    84|  } catch {
    85|    // Non-fatal
    86|  }
    87|}
    88|
    89|async function reportHealth(): Promise<void> {
    90|  const memUsage = process.memoryUsage();
    91|  console.log('[IVX Worker] Health report', {
    92|    marker: WORKER_MARKER,
    93|    uptime: Math.floor((Date.now() - new Date(state.startedAt).getTime()) / 1000),
    94|    jobsProcessed: state.jobsProcessed,
    95|    jobsFailed: state.jobsFailed,
    96|    rssMB: Math.round(memUsage.rss / 1024 / 1024),
    97|    heapMB: Math.round(memUsage.heapUsed / 1024 / 1024),
    98|    lastJobAt: state.lastJobAt,
    99|  });
   100|  state.lastHealthReport = new Date().toISOString();
   101|}
   102|
   103|async function main(): Promise<void> {
   104|  console.log('[IVX Worker] Starting background worker', {
   105|    marker: WORKER_MARKER,
   106|    env: process.env.IVX_DEPLOYMENT_ENV ?? 'unknown',
   107|    workerMode: process.env.IVX_WORKER_MODE === 'true',
   108|  });
   109|
   110|  let healthCounter = 0;
   111|  let cleanupCounter = 0;
   112|
   113|  while (state.running) {
   114|    try {
   115|      await processAgentJobs();
   116|
   117|      healthCounter++;
   118|      if (healthCounter * POLL_INTERVAL_MS >= HEALTH_REPORT_INTERVAL_MS) {
   119|        await reportHealth();
   120|        healthCounter = 0;
   121|      }
   122|
   123|      cleanupCounter++;
   124|      if (cleanupCounter * POLL_INTERVAL_MS >= 6 * 60 * 60 * 1000) {
   125|        await cleanupOldAuditLogs();
   126|        cleanupCounter = 0;
   127|      }
   128|
   129|      await new Promise((resolve) => setTimeout(resolve, POLL_INTERVAL_MS));
   130|    } catch (err) {
   131|      console.error('[IVX Worker] Poll cycle error', {
   132|        marker: WORKER_MARKER,
   133|        error: err instanceof Error ? err.message : String(err),
   134|      });
   135|      await new Promise((resolve) => setTimeout(resolve, POLL_INTERVAL_MS));
   136|    }
   137|  }
   138|}
   139|
   140|process.on('SIGTERM', () => {
   141|  console.log('[IVX Worker] SIGTERM received, shutting down', { marker: WORKER_MARKER });
   142|  state.running = false;
   143|  setTimeout(() => process.exit(0), 2000);
   144|});
   145|
   146|process.on('SIGINT', () => {
   147|  console.log('[IVX Worker] SIGINT received, shutting down', { marker: WORKER_MARKER });
   148|  state.running = false;
   149|  setTimeout(() => process.exit(0), 2000);
   150|});
   151|
   152|main().catch((err) => {
   153|  console.error('[IVX Worker] Fatal error', {
   154|    marker: WORKER_MARKER,
   155|    error: err instanceof Error ? err.message : String(err),
   156|  });
   157|  process.exit(1);
   158|});

