   128|      err.name = 'IVXAIGatewayTimeoutError';
   129|      reject(err);
   130|    }, timeoutMs);
   131|    promise.then(
   132|      (value) => {
   133|        clearTimeout(timer);
   134|        resolve(value);
   135|      },
   136|      (error) => {
   137|        clearTimeout(timer);
   138|        reject(error);
   139|      },
   140|    );
   141|  });
