   102|/** Exponential backoff with jitter. attempt is 1-based. */
   103|export function computeRetryDelayMs(
   104|  attempt: number,
   105|  baseMs: number = 2_000,
   106|  capMs: number = 60_000,
   107|  jitterRatio: number = 0.25,
   108|  random: () => number = Math.random,
   109|): number {
