   204|export async function handleEngineeringTaskApprove(request: Request): Promise<Response> {
   205|  try {
   206|    const { context } = await assertIVXRegisteredOwnerBearer(request, 'engineering_task_approve');
   207|    const body = await readBody(request);
   208|    if (body.confirm !== true || readString(body.confirmText) !== IVX_ENGINEERING_APPROVAL_PHRASE) {
   209|      return ownerOnlyJson({
   210|        status: 'error',
   211|        confirmationRequired: true,
   212|        error: `Owner approval of a production deploy requires confirm:true and confirmText:"${IVX_ENGINEERING_APPROVAL_PHRASE}".`,
   213|      }, 409);
   214|    }
   215|    const result = await approveEngineeringTask({
   216|      taskId: readString(body.taskId),
   217|      approvedBy: context.email ?? 'owner',
   218|    });
   219|    return ownerOnlyJson({ status: result.ok ? 'ok' : 'error', task: result.task, error: result.error }, result.ok ? 200 : 400);
   220|  } catch (error) {
   221|    return errorResponse(error);
   222|  }
   223|}
   224|
   225|/**
   226| * POST /api/ivx/engineering-os/activate — owner-approved Phase 1 activation.
   227| * Flips all 12 teams to ACTIVE. Requires confirm:true + the exact activation
   228| * phrase; otherwise responds 409 confirmationRequired (sensitive-action pattern).
   229| */
   230|export async function handleEngineeringActivate(request: Request): Promise<Response> {
   231|  try {
   232|    const { context } = await assertIVXRegisteredOwnerBearer(request, 'engineering_os_activate');
   233|    const body = await readBody(request);
   234|    if (body.confirm !== true || readString(body.confirmText) !== IVX_ENGINEERING_ACTIVATION_PHRASE) {
   235|      return ownerOnlyJson({
   236|        status: 'error',
   237|        confirmationRequired: true,
   238|        error: `Engineering OS activation requires confirm:true and confirmText:"${IVX_ENGINEERING_ACTIVATION_PHRASE}".`,
   239|      }, 409);
   240|    }
   241|    const result = await activateEngineeringOS({ approvedBy: context.email ?? 'owner' });
   242|    const activation = await getEngineeringActivation();
   243|    return ownerOnlyJson({
   244|      status: result.ok ? 'ok' : 'error',
   245|      activatedTeams: result.activatedTeams,
   246|      alreadyActive: result.alreadyActive,
   247|      approvedBy: result.approvedBy,
   248|      activation,
   249|      error: result.error,
   250|    }, result.ok ? 200 : 502);
   251|  } catch (error) {
   252|    return errorResponse(error);
   253|  }
